function createEnv(sdk) {
  var MAX_STEPS = 1600;
  var rng, basketX, appleX, appleY, active, delay;
  var ticks, caught, misses, done;
  var terms = [0, 0, 0, 0];
  var obs = [0, 0, 0, 0, 0, 0, 0, 0, -1];

  function difficulty() {
    return Math.min(1, ticks / 900);
  }

  function fallSpeed() {
    return 2.6 + 3.2 * difficulty();
  }

  function basketHalfWidth() {
    return 54 - 14 * difficulty();
  }

  function spawnApple() {
    appleX = rng.range(55, 745);
    appleY = 24;
    active = true;
  }

  return {
    reset: function (seed) {
      rng = sdk.rng(seed);
      basketX = 400;
      caught = 0;
      misses = 0;
      ticks = 0;
      done = false;
      active = true;
      delay = 0;
      appleX = rng.range(55, 745);
      appleY = 24;
      terms[0] = 0;
      terms[1] = 0;
      terms[2] = 0;
      terms[3] = 0;
    },

    step: function (action) {
      if (done) return;

      if (action === 0) basketX -= 8.5;
      else if (action === 2) basketX += 8.5;
      basketX = sdk.clamp(basketX, 56, 744);

      ticks += 1;
      terms[2] += 0.01;

      if (active) {
        var dx = Math.abs(appleX - basketX);
        terms[1] += Math.max(0, 1 - dx / 300) / 100;

        appleY += fallSpeed();
        if (appleY >= 420) {
          if (Math.abs(appleX - basketX) <= basketHalfWidth() + 7) {
            caught += 1;
            terms[0] += 1;
            if (caught >= 12) {
              done = true;
            }
          } else {
            misses += 1;
            terms[3] += 1;
            if (misses >= 3) done = true;
          }

          active = false;
          delay = Math.max(4, 16 - Math.floor(ticks / 120));
        }
      } else if (!done) {
        delay -= 1;
        if (delay <= 0) spawnApple();
      }

      if (ticks >= MAX_STEPS) done = true;
    },

    observe: function () {
      var speed = fallSpeed();
      var y = active ? appleY : 440;
      var x = active ? appleX : basketX;
      var timeToCatch = active ? Math.max(0, (420 - appleY) / speed) : 80;

      obs[0] = (basketX - 400) / 344;
      obs[1] = (x - 400) / 345;
      obs[2] = sdk.clamp(y / 215 - 1, -1, 1);
      obs[3] = (speed - 4.2) / 2;
      obs[4] = sdk.clamp((x - basketX) / 400, -1, 1);
      obs[5] = sdk.clamp(timeToCatch / 40 - 1, -1, 1);
      obs[6] = misses / 3;
      obs[7] = caught / 12;
      obs[8] = active ? 1 : -1;
      return obs;
    },

    get done() {
      return done;
    },

    terms: terms,

    render: function (draw, ghost) {
      var half = basketHalfWidth();
      var basketY = 430;

      if (!ghost) {
        draw.clear(sdk.colors.bg);
        draw.line(36, 446, 764, 446, sdk.colors.dim, 2);
        draw.line(36, 420, 764, 420, sdk.colors.warn, 1);
        draw.text("Caught: " + caught + " / 12", 36, 30, sdk.colors.fg, 18);
        draw.text("Misses: " + misses + " / 3", 650, 30, sdk.colors.fg, 18);

        if (active) {
          draw.circle(appleX, appleY, 11, sdk.colors.good);
          draw.line(appleX, appleY - 10, appleX + 2, appleY - 18, sdk.colors.warn, 3);
          draw.circle(appleX + 8, appleY - 15, 5, sdk.colors.accent);
        }
      }

      draw.poly(
        [
          basketX - half, basketY - 15,
          basketX + half, basketY - 15,
          basketX + half - 9, basketY + 8,
          basketX - half + 9, basketY + 8
        ],
        sdk.colors.accent,
        false
      );
      draw.line(basketX - half, basketY - 15, basketX + half, basketY - 15, sdk.colors.good, 4);
    },

    humanAct: function (input) {
      if (input.held.has("ArrowLeft")) return 0;
      if (input.held.has("ArrowRight")) return 2;
      return 1;
    }
  };
}
